import{_ as s,I as n,o as i,c as l,a6 as d,J as t,j as a,a as r}from"./chunks/framework.9ylqSDY5.js";const v=JSON.parse('{"title":"Observatory Headquarters","description":"","frontmatter":{"title":"Observatory Headquarters","visibility":"public","audience":"admin","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/team/index.md","filePath":"guides/team/index.md"}'),h={name:"guides/team/index.md"};function m(u,e,p,g,c,b){const o=n("ToolShot");return i(),l("div",null,[e[0]||(e[0]=d('<h1 id="observatory-headquarters" tabindex="-1">Observatory Headquarters <a class="header-anchor" href="#observatory-headquarters" aria-label="Permalink to “Observatory Headquarters”">​</a></h1><p>Every Arcsecond.local installation is <strong>multi-user by design</strong>. You do not opt into a separate &quot;organisation&quot; or &quot;portal&quot; product — the moment you run Arcsecond.local, you are running a shared space for your whole observatory, science group, university, planetarium or astronomy club. <strong>Observatory Headquarters</strong> is the app where that shared life is managed.</p><blockquote><p>&quot;All astronomical observatories in the world have in common the needs to prepare and plan observations, organise and execute night operations, then store, package and distribute data.&quot;</p><p>— Cédric Foellmi, Ph.D. (former <a href="https://www.eso.org/sci/publications/messenger/archive/no.121-sep05/messenger-no121-69-69.pdf" target="_blank" rel="noreferrer">ESO Fellow in La Silla</a>, and Arcsecond Founder)</p></blockquote><p>The other three apps — <a href="/guides/observing/night-studio">Night Studio</a>, the <a href="/guides/observing/control-room">Control Room</a> and <a href="/guides/data/">Data Grand Central</a> — are the same for <strong>every member</strong> of your install. Observatory Headquarters adds the organisation-wide layer on top of them.</p><h2 id="what-it-gives-you" tabindex="-1">What it gives you <a class="header-anchor" href="#what-it-gives-you" aria-label="Permalink to “What it gives you”">​</a></h2><ul><li><strong>A single home for the whole life of your observatory</strong> — the history of all observations, observers, targets and observing nights, and a modern data archive built on the same APIs that power the rest of the platform, even for data located elsewhere (see <a href="/guides/data/external-storages">External Storages</a>).</li><li><strong>An unlimited number of members</strong>, with four clear roles (<a href="./permissions">Permissions &amp; Roles</a>) to control who can do what and who can access what.</li><li><strong>Sharing</strong>, from a private dataset between two members up to a customizable public page exposing selected data to the world.</li><li><strong>An observatory schedule, a map, storages and settings</strong> shared by everyone, each with <a href="#the-tools">its own tool</a>.</li></ul><h2 id="members-and-roles" tabindex="-1">Members and roles <a class="header-anchor" href="#members-and-roles" aria-label="Permalink to “Members and roles”">​</a></h2><p>Membership and access are governed by four roles, <code>Visitor</code>, <code>Member</code>, <code>Admin</code> and <code>Owner</code>, on top of what anyone may see in public. What each role is for is on the <a href="./permissions">Permissions &amp; Roles</a> page, and the complete list of rights, generated from the server, on the <a href="/reference/permissions">Roles and permissions</a> page.</p><h2 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to “The tools”">​</a></h2><h3 id="schedule" tabindex="-1">Schedule <a class="header-anchor" href="#schedule" aria-label="Permalink to “Schedule”">​</a></h3><p>One calendar for the whole observatory. Nights fill in by themselves from your data, beside the events you add: maintenance, meetings, visitors. Events can recur, and name telescopes, observers and night operators.</p>',11)),t(o,{tool:"observatory-schedule"}),e[1]||(e[1]=a("h3",{id:"map",tabindex:"-1"},[r("Map "),a("a",{class:"header-anchor",href:"#map","aria-label":"Permalink to “Map”"},"​")],-1)),e[2]||(e[2]=a("p",null,"A drawing of the observatory and of how it is linked: sites, domes, buildings, rooms, telescopes, equipment, computers, software and network. It starts from your registry; admins arrange it. Members only.",-1)),t(o,{tool:"observatory-map"}),e[3]||(e[3]=a("h3",{id:"data-storages",tabindex:"-1"},[r("Data Storages "),a("a",{class:"header-anchor",href:"#data-storages","aria-label":"Permalink to “Data Storages”"},"​")],-1)),e[4]||(e[4]=a("p",null,[r("Where the data lives, and how it gets there. Admins attach storages (SMB, S3, SFTP...) to which new data files and database backups are pushed. See "),a("a",{href:"/guides/data/external-storages"},"External storages"),r(".")],-1)),t(o,{tool:"data-storages"}),e[5]||(e[5]=a("h3",{id:"settings",tabindex:"-1"},[r("Settings "),a("a",{class:"header-anchor",href:"#settings","aria-label":"Permalink to “Settings”"},"​")],-1)),e[6]||(e[6]=a("p",null,"Activation, email, file naming, appearance and preferences. Admins only.",-1)),t(o,{tool:"observatory-settings"}),t(o,{tool:"observatory-settings",index:1})])}const y=s(h,[["render",m]]);export{v as __pageData,y as default};
